def existing(n,asset,title,short,features,included=None,variants=None,spec=None,safety=None,price=None,kind='catalog'):
 r=dict(byid[f'KD-R{n:03}']);r.update(title=title,shortDescription=short,description=short+' '+ ' '.join(features),features=features,images=['/images/catalog/kiddio-'+asset+'.webp'],classification=kind)
 if included is not None:r['included']=included
