 if spec is not None:r['specifications']=[{'name':k,'value':v} for k,v in spec]
 if price is not None:r['supplier']['supplierPrice']=price
 r['safety']=safety or 'Check the item before use and follow the instructions on its packaging. Keep packaging away from children. Adult supervision is required.'
 selected.append(r);return r
