 r={'researchId':f'KD-R{n:03}','productId':'a2'+format(n,'022x'),'title':title,'slug':re.sub('[^a-z0-9]+','-',title.lower()).strip('-'),'category':cat,'description':short+' '+' '.join(features),'shortDescription':short,'features':features,'specifications':[{'name':k,'value':v} for k,v in spec],'included':included,'variants':variants or [],'ageGroups':[],'images':['/images/catalog/kiddio-'+asset+'.webp'],'supplier':{'platform':'Meesho','supplierUrl':url,'supplierProductCode':code,'supplierPrice':cost,'priceCheckedAt':'2026-09-15','priceBasis':'Live browser displayed listing price, not a delivered quote.','availability':'available at research check','notes':'Desk research only; no physical sample inspection or certification is implied.'},'classification':kind,'safety':safety or 'Adult supervision is required. Keep packaging away from children. Check the item before each use and follow the instructions supplied.'}
